let validFirstNames = ["Nathan", "Camila", "Layara", "Gustavo", "Kessidy", "João Pedro", "Clarice", "Nelcileia", "Adilon", "Caio", "Elias", "Marcos", "Nicolas", "Antônio"];

let invalidFirstNamesNumericString = ["123", "1300385", "1234567890987"];

let invalidFirstNamesNumber = [123, 1029376, 1098236745637];

let lastNames = ["da Silva", "dos Santos", "de Souza", "Matos", "Baptista", "Luz", "de Oliveira", "Ferreia", "Moreira", "Pereira"]

function randomItem(array) {
    return array[Math.floor(Math.random() * array.length)];
}

let firstNameTypes = [
    {
        type: "valid",
        values: validFirstNames
    },
    {
        type: "numericString",
        values: invalidFirstNamesNumericString
    },
    {
        type: "number",
        values: invalidFirstNamesNumber
    }
];

let selectedType = randomItem(firstNameTypes);

let selectedFirstName = randomItem(selectedType.values);

let selectedLastName = randomItem(lastNames);

let fullName;

if (selectedType.type === "number") {
    fullName = selectedFirstName;
} else {
    fullName = selectedFirstName + " " + selectedLastName;
}

pm.variables.set("fullName", JSON.stringify(fullName));


let emailDomains = ["@gmail.com", "@hotmail.com", "@yahoo.com", "@outlook.com"];

function randomNumber() {
    return Math.floor(Math.random() * 1000000);
}

let selectedDomain = randomItem(emailDomains);
let selectedNumber = randomNumber();

let email = selectedFirstName+selectedNumber+selectedDomain;

pm.variables.set("email", JSON.stringify(email));

let validPassword = ["1234", "12382374", "123456789012"];
let invalidPassword = ["123", "1234567890987", 123];



let passwordTypes = [
    {
        type: "valid",
        values: validPassword
    },
    {
        type: "invalid",
        values: invalidPassword
    }];


let selectedPasswordType = randomItem(passwordTypes);
let selectedPassword = randomItem(selectedPasswordType.values);

pm.variables.set("password", JSON.stringify(selectedPassword));

let confirmPassword = selectedPassword;

pm.variables.set("confirmPassword", JSON.stringify(confirmPassword));


let accessProfile = ["admin", "TI", "user"];
let selectedAccessProfile = randomItem(accessProfile);

pm.variables.set("accessProfile", JSON.stringify(selectedAccessProfile));



